// Standard-library analysis of rendered PNGs. No model or camera execution.
import javax.imageio.ImageIO;import java.nio.file.*;import java.util.*;
public class AlphaBounds{public static void main(String[]a)throws Exception{int count=0,minTop=99999,maxTop=-1,minLeft=99999,maxRight=-1;long headEdge=0,minPartial=Long.MAX_VALUE,maxPartial=0;List<String>bad=new ArrayList<>();try(var stream=Files.list(Path.of(a[0]))){for(Path p:stream.filter(x->x.getFileName().toString().matches("frame-[0-9]{6}\\.png")).sorted().toList()){var im=ImageIO.read(p.toFile());if(im.getWidth()!=600||im.getHeight()!=780)throw new IllegalStateException("Unexpected dimensions");int top=780,left=600,right=-1;long partial=0;for(int y=0;y<im.getHeight();y++)for(int x=0;x<im.getWidth();x++){int alpha=im.getRGB(x,y)>>>24;if(alpha>0&&alpha<255)partial++;if(alpha>=16&&y<280){top=Math.min(top,y);left=Math.min(left,x);right=Math.max(right,x);if(x==0||x==599||y==0)headEdge++;}}minTop=Math.min(minTop,top);maxTop=Math.max(maxTop,top);minLeft=Math.min(minLeft,left);maxRight=Math.max(maxRight,right);minPartial=Math.min(minPartial,partial);maxPartial=Math.max(maxPartial,partial);if(top<12||left<12||right>588)bad.add(p.getFileName().toString());count++;}}
String report="{\"frames\":"+count+",\"headBand\":[0,0,600,280],\"alphaThreshold\":16,\"topMarginMinPx\":"+minTop+",\"topMarginMaxPx\":"+maxTop+",\"headAlphaLeftMinPx\":"+minLeft+",\"headAlphaRightMaxPx\":"+maxRight+",\"headEdgeContactPixels\":"+headEdge+",\"partialAlphaCountRange\":["+minPartial+","+maxPartial+"],\"failedFrames\":["+String.join(",",bad.stream().map(s->"\""+s+"\"").toList())+"],\"scope\":\"All rendered PNG head-band margins; bust sleeve/torso edges intentionally cropped\"}";Files.writeString(Path.of(a[1]),report);System.out.println(report);if(count!=Integer.parseInt(a[2])||!bad.isEmpty()||headEdge!=0)System.exit(2);}}
